/**
 * League tasks (https://oldschool.runescape.wiki/w/Trailblazer_Reloaded_League/Tasks,
 * https://oldschool.runescape.wiki/w/Raging_Echoes_League/Tasks,
 * https://oldschool.runescape.wiki/w/Demonic_Pacts_League/Tasks): the catalog each league's
 * characters complete for League Points, awarded from the game by data-driven triggers (kills,
 * levels and quests in Triggers, deeds in Actions), and the cache's task list interface opened from
 * the league side panel. The catalog (data/league-tasks.json) is generated by
 * scripts/generate-league-tasks.ts; Demonic Pacts' is the cache's own list, and an older league's is
 * sent to the client as enum and DB row overrides.
 * Points and the award itself are LeaguePoints'; other plugins complete a task with
 * `league:complete-task` { player, id } (docs/leagues.md).
 */
const Common = require("./leaguetasks/Common.LeagueTasks");

module.exports = {
  name: "LeagueTasks",
  members: true,
  dependsOn: ["LeagueMode", "LeaguePoints"],
  register(api) {
    Common.init(api);
    require("./leaguetasks/Catalog.LeagueTasks")(api);
    require("./leaguetasks/Complete.LeagueTasks")(api);
    require("./leaguetasks/Interface.LeagueTasks")(api);
    require("./leaguetasks/Triggers.LeagueTasks")(api);
    require("./leaguetasks/Actions.LeagueTasks")(api);
    require("./leaguetasks/Commands.LeagueTasks")(api);
  },
};
